    allowanceIntro: 'ኣብ DeHub ምውጻእ መዓልታዊ ብነጻ እዩ ፣ እዚ ድማ ምስ ባጅካ ዚመሳሰል ክፍሊት እዩ ። ኩሉ ሰብ ብ10 ናይ ጽሑፍ ልኡኽታትን ሓደ ጊጋባይት ቪድዮታትን ስእልታትን ድምጽን መዓልታዊ ይጅምር ። ሓደ ወይ ካብኡ ሓሊፉ ፡ እቲ ዝተረፈ መዓልቲ ድማ ኣብ DeHub ምልክታት ይኽፈል — 10c ናይ ጽሑፍ ጽሑፍ ጽሑፍ ፡ $ 2 ጊጋባይት ፡ ኣብ ልዕሊኡ ጥራይ እዩ ዚኽፈል ።',
    allowanceIntro2: 'ናይ ጽሑፍ ልኡኽታትን መራኸቢ ብዙሓን ዝተፈለዩ ገንዳታት እዮም ። ካብ ሓደ ምውጻእ ነቲ ካልእ ኣይትንክፎን እዩ ፣ ስለዚ ሓደ መዓልቲ ቪድዮ ምስትውዓል ፡ ንኹሎም ዓሰርተ ናይ ጽሑፍ ልኡኽታት ብነጻ ይሓድጎ ። ክልቲኦም ኣብ ፍርቂ ለይቲ UTC ክኣትዉ እዮም ።',
    allowanceHowTitle: 'ብኸመይ ከም እትኸፍል',
    allowanceHowDesc: 'እቲ ትእዛዝ ኣገዳሲ እዩ ፡ ብዕላማ ድማ እዩ ፦ ንዘይተሓትመ ጽሑፍ ክትከፍል ኣይትኽእልን ኢኻ ፡ ድሕሪኡ ድማ ክትከፍሎ ከም ዘይትኽእል ክትነግሮ እትኽእል ዓቢ ፋይል ክትለኣኽ ኣይትኽእልን ኢኻ ።',
    allowanceStep2: 'እቲ ቦታኻ ልክዕ ከምቲ ኣብ ውሽጢ እቲ ናጻ ድጎማ ዘሎ እዩ ዚነብር ። ሕትመት ፈጺሙ ክፍሊት ኣይጽበን እዩ ።',
    allowanceStep3Title: 'ንስኻ ኢኻ እትኸፍል',
    allowanceStep3: 'ሓደ ምትሕልላፍ ፡ ሓደ ፊርማ ፡ ነዚ ጽሑፍ እዚ ጥራይ እዩ ። እዚ ድማ ኣብ ዝኾነ ይኹን መሰረታዊ ወይ BnB ሰንሰለት እኹል DeHub ምልክታት ዘለዎ እዩ ዝምርኮስ ።',
    allowanceUnpaidTitle: 'እንተ ኣቋሪጽካ',
    allowanceUnpaidDesc: 'እቲ ጽሑፍ ተሓቲሙ እዩ ። እቲ ዘይተኸፍለ መጠን ኣብ ልዕሊ መለያኻ ክፉት ኮይኑ ክሳብ ዝዕረቕ ቀጻሊ ክፍሊትካ ይዓግት — ግን ፈጺሙ ነጻ ኣይኮነን ። እቲ ጽባሕ ዝህበካ ሓገዝ ፡ ኩሉ ግዜ ናትካ እዩ ፡ ዋላ ሓደ ነገር ጽቡቕ ይኹን ኣይኹን ።',
    allowanceCountsTitle: 'እንታይ እዩ ዚኸፍል ፧',
    allowanceCounts1: 'ሓደ ኻብቲ መዓልታዊ ጽሑፋትካ ጥራይ እዩ ዜሕልፎ ።',
    allowanceCounts4: 'እቲ ልሙድ ፡ ምሉእ ጊጋባይት ዘይኰነስ ፡ ፕሮ-ሬታ እዩ ። 200 ሜባ ናይ ምውሳድ ክፍሊትካ እንተ ሓሊፉ ፡ 200 ሜባ ትኸፍል ኢኻ ።',
    allowanceCounts5: 'መልሲ ፡ ርእይቶ ፡ ግብረ መልሲ ፡ ምኽርን መልእኽትን ዋጋ የብሉን ፡ ነቲ ሓገዝ ድማ ፈጺሙ ኣይትንክፎን እዩ ።',
    allowanceBadgeNote: 'ሓደ ባጅ ኣብ ሓደ እዋን ክልቲኡ ፍርቂ ይንቀሳቐስ — እቲ ዝዓበየ ናጻ ድጎማታትን ኣብ ዝሓለፈ ዝኾነ ነገር ዝነኣሰ ዋጋን ። እቲ ቅናሽ ሓደ ዓይነት ናይ መሰጋገሪ ባጅ ሒዞም ፡ DeHub ምልክታት ምስ ዚዕድጉ ፡ ካብ 5% ኣብ ክራብ ናብ 30% ኣብ ሜጋሎዶን ኪዕድጉ ኸለዉ ፡ ድሮ ይረኽቡ እዮም ፣ ስለዚ ፡ ሓደ መልሲ ብዛዕባ እቲ ባጅ ዚግብኦ እዩ ። እቲ ሓገዝካ ካብ\'ቲ ዝረኸብካዮ ባጅ ዝመጸ እዩ ፦ ኣብ መገለጺኻ ናይ ሓላዊ ትርኢታት ናይ ደረጃ ልቓሕ ክህበካ ይኽእል እዩ ፣ ግን ናይ ልኡኽ ድጎማኦም ኣይህበካን እዩ ።',
