    tokenDisclaimer: 'DeHub ምልክታት ኣብ ውሽጢ ስነ ምህዳርና ከም ናይ ጸወታ ምንቅስቓስ ዝመስል ናይ ጥቕሚ ምልክታት ኮይኑ ይሰርሕ ፡ ከምኡ\'ውን ናይ ኢንቨስትመንት መካይን ኣይኮነን ። እቲ ናይ blockchain መሰረተ ልምዓትና ንዘይተራእየ ግልፅነትን ንዘይተረጋገጸ ሓበሬታን ንትምህርታዊ ዕላማታት ዘቕርብ እኳ እንተዀነ ፡ ኩሎም ዕዳጋታት ሓደገኛ ሓደጋታት የጋጥሞም እዩ ። ብሰንኪ ተለዋዋጭነት ዕዳጋ ፡ ቴክኒካዊ ጉዳያት ፡ ግህሰት ጸጥታ ፡ ወይ ዘይተጸበኻዮ ኩነታት ፡ ምሉእ ኢንቨስትመንትካ ክትጠፍእ ትኽእል ኢኻ ። ምሉእ ብምሉእ ክትጠፍእ እትኽእል ገንዘብ ጥራይ ኢኻ እትሳተፍ ። DeHubን ብጾቱን ንዝተፈጠረ ዝኾነ ይኹን ናይ ገንዘብ ጉድኣት ሓላፍነት ኣይወስዱን እዮም ።',
    exploreTitle: 'ነቲ መተግበሪ & Beyond መርምር',
    exploreDesc: 'ናይ ምርምር ባርታት ንYouTubeን ካልኦት ዓበይቲ ናይ ስርሒት መተግበሪ ኤፒአይታትን ብሓባር ብምእካብ ፡ ብዙሕ መተግበሪታት ክትስሕብ ከለኻ ፡ እቲ ናይ ምርምር ገጽ ፡ ናይ ህያው ማሕበረሰብ ቻትናን ናይ መሪሕነት ሰሌዳታትን እውን ይሕዝ ፡',
    exploreFormula: 'እዚ ድማ ነቲ ናይ ኣፕል ኣታዊ ክፋል (RS) ብሓባር ክውስኖ እዩ ። እቲ ቅኑዕ ስልተ ቀመር ነዚ ኣብ ትሕቲ ቤታ እዩ ዘሎ ፡ ብመሰረት እቲ ዝተፈጥረ ኣታዊ (RG) ድማ ኪቕየር ኣለዎ ።',
    exploreAlgorithm: 'እዚ ድማ እቲ ቀንዲ ስልተ ቀመር እዩ ፣ እቲ ናይ ሽልማት ተመክሮታት ድማ ፍጹም ሚዛን ክሳብ ዝረክብ ኣብ ፈተነታትን ጌጋታትን መሰረት ክቕጽል እዩ ።',
    badgeTitle: 'ባጅካ ኣማዕብል',
    badgeSubtitle: 'ናይ ክብሪ ሞዴል ባጅ',
