    badgePriceTitle: 'ኣብ ኣሜሪካ ዝንቀሳቐስ ገንዘብ ፡ ዶላር',
    badgePriceDesc: 'እቶም 13 ደረጃታት ፡ ብሜጋሎዶን ኣቢሎም ክራብ ፡ ነፍሲ ወከፎም ኣብ ክንዲ ሓደ ውሱን ቁጽሪ ምልክታት ፡ ሓደ ውሱን መጠን ዶላር የኽፍሉ እዮም ። እቲ ደሆብ ዚሓትት ምልክት ፡ እቲ ዶላር ብቀጥታ ዋጋ ኸም ዚኸፍል እዩ ዚገልጽ ። ስለዚ ፡ ሓደ ባጅ ፡ እቲ ዕዳጋ ዚገብሮ ዘበለ ፡ ሓደ ዓይነት ውዕለት እዩ ዜመልክት ። ክልተ መከላኸሊታት ይመጽእ ኣሎ ፡ እቲ ዝድለ ዋጋ እንተወደቐ ፡ ካብቲ ዝተሓትመ ቁጽሪ ንላዕሊ ኣይውስኽን እዩ ፣ ሓደ ግዜ ድማ ሓደ ደረጃ ምስ በጽሐካ ፡ እቲ ዝረኸብካዮ ባጅ ነቲ ዝረኸብካዮ ርሑቕ ብቕዓት ተዓጽዩ ስለ ዘሎ ፡ ሓደ ዲፕ ክመልሶ ኣይክእልን እዩ ።',
    badgeUnlockTitle: 'ከመይ ዝበለ ባጅ ይኽፈት',
    badgeUnlock1: 'ኣብ ምኽርታት ፡ ኣብ ናይ ክፍሊት ርእይቶታት ፡ ኣብ ምዝገባታትን ኣብ ኣታዊታትን ዝወሓደ ክፍሊት ፡ ኣብ ደረጃ 0.69% ይንኪ ።',
    badgeUnlock2: 'እቲ ዝዓበየ ናይ ዕለታዊ ናጻ ናይ ፖስታ ድጎማ ፡ ከምኡ\'ውን ኣብ ዝሓለፈ ዝኾነ ነገር ቅናሽ ።',
    badgeUnlock3: 'እቲ ናይ DeHub ምልክታት ምስ እትዕድግ ተመሳሳሊ ቅናሽ ፡ ካብ 5% ኣብ ክራብ ናብ 30% ኣብ ሜጋሎዶን ።',
    badgeUnlock5: 'ዝያዳ ክብደት ብዛዕባ እቲ እትገብሮ ፦ ርእይቶ ወይ ግብረ መልሲ ናይ ሓደ ባጅ ሓላፊ ፡ ኣብ ሓደ ደረጃ ፡ ከም ናይ ምምሕዳር ድምጺ ፡ ሓደ ብዘይ ባጅ ፡ ክልተ ኣብ ክራብ ፡ ከምኡውን ኣብ ልዕሊኡ ኣብ ሜጋሎዶን ንዝርከቡ ኣርባዕተ ደረጃታት ዝያዳ ይቑጸር ። እዚ ኣብ ሓደ ግብረ መልሲኻ ብዙሕነት ዘለዎ እዩ ፣ ካልኣይ ድማ ፈጺሙ ኣይተርፍን እዩ ።',
    badgeDelegationTitle: 'ነቲ ባጅካ ልኢኽዎ',
    badgeDelegationDesc: 'ሓደ ባጅ ልቓሕ ክኸውን ይኽእል እዩ ። ነፍሲ ወከፍ ዝደለኻዮ ሩጫ ፡ ሓደ ኣብ ክራብ ፡ 13 ኣብ ሜጋሎዶን ፡ ካልእ ናይ ገዛእ ርእስኻ ደረጃ ሒዝካ ኽሳዕ እትወጽእ ፡ ሓደ ናይ ልኡኽ ቦታ ይህበካ ። እዚ ድማ ኣብ DeHub ዘሎ ጽልዋ ፡ ኣብ ክንዲ ኣብ ሓደ ቦርሳ ኮፍ ኢልካ ምስ ሓደ ጉጅለ ክትጓዓዝ ስለ ዝዓለመ እዩ ዘሎ ፡ ሰራሕተኛታት ፡ ጋንታታትን ካልኣይቲ ሕሳብን ፡ ብዘይ ዝኾነ ሰብ ምልክታት ከይንቀሳቐሱ ወይ ቁልፊ ከይሓልፍ ፡ ነቲ ደገፍኦም ይረኽቡ እዮም ።',
    badgeDelegationB1: 'ሓደ ዓይነት ደረጃ ፡ ሓደ ካብዞም ዝስዕቡ ኣይኮነን ።',
    badgeDelegationB1Desc: 'ሜጋሎዶን ንሜጋሎዶን ኣበጊሱ እዩ ። ሓደ ባጅ ነቲ እትእዝዞ ጽልዋ ይገልጽ ፡ ስለዚ እቶም ዝምለሱኻ ሰባት ነቲ እትሸከሞ ነገር ይገብሩ እዮም ።',
    badgeDelegationB2: 'ስሎታት ካብ ገዛእ ርእስኻ እዮም ዚመጹ ፦',
    badgeDelegationB2Desc: 'እቲ እተበደለ ባጅ ናይ ገዛእ ርእሱ ኣፈታትሓ የብሉን ፣ ስለዚ ናይ ልቓሕ ደረጃ ፈጺሙ ክበድእ ኣይክእልን እዩ ።',
    badgeDelegationB3: 'እዚ ድማ ከምዚ ዚስዕብ እዩ ፦',
    badgeDelegationB3Desc: 'ኣብ ዝኾነ ቦታ ኣብ ኣፕሊኬሽን ዝተወሃበ ባጅ ጠውቑ ፡ መን ከም ዝድግፎ ድማ ስም ኣለዎ ። ካብ ኣበይ ከም ዝመጸ ዚሕባእ ነገር የለን ።',
    badgeDelegationB4: 'ኣብ ዝኾነ እዋን ፡',
    badgeDelegationB4Desc: 'ንድሕሪት ተመሊስካ ፡ እቲ ደረጃ ድማ ናባኻ ተመልሰ ። እቲ ዝደለኻዮ ፡ እቲ ዝደለኻዮ ፡ እቲ ዝደለኻዮ ፡',
    badgeDelegationB5: 'ኩነታት ፡ መሰል የብሉን ፦',
    badgeDelegationB5Desc: 'ሓደ ናይ ልቓሕ ባጅ እቲ መድረኽ ዘርኢ እዩ ፣ ነቲ ምስ ደረጃ ዚኸይድ ክብደት ድማ ይሕዝ — እቲ ልቓሕ ዝነበረ ደረጃ ፡ ርእይቶ ወይ ግብረ መልሲ ይቑጸር እዩ ። እቲ ዘይሸከሞ ነገር ብገንዘብ ዝተኸፍለ ነገር እዩ ፦ ናይ ክፍሊት ደረጃኻ ፣ ናይ ምልክት መግዛእቲ ቅናሽካ ፣ ናይ ዕለታዊ ናይ ልኡኽ ድጎማኻን ናይ ገዛእ ርእስኻ ልኡኽ ኣፈፃፅማታትካን ገና ካብ ገዛእ ርእስኻ እትሕዝዎ ክፋል ይነበብ ኣሎ ።',
    badgeDelegationB6: 'ነቲ እተቐበሎ ተመሳሳሊ በረኸት ። *',
    badgeDelegationB6Desc: 'ሓደ ኣፈፃፅማ ነቲ ዝለዓለ ደረጃኻ ክህበካ ኣየድልዮን እዩ ። ነቲ ዘይዕጸወ ዕንጨይቲ ሕረዶ ፡ ሓደ ሰብ ድማ ብዘይ ሜጋሎዶን ኣብ ንጉስ ኮብራ ንድሕሪት ተመሊስካ ።',
