    badgeDelegationB7Desc: 'እቲ ናብ መለያ ዝቐረበ ባጅ ኣብ ናይ ኣፍልጦ ደወልኡ ይርአ ፣ ክኽሕዶ ይኽእል እዩ ። ሓደ ኻባኻትኩም ድሕሪኡ ሓደ ልኡኽ ኪውዳእ ይኽእል እዩ ።',
    tipTitle: 'ንፍቕሪኻ ኣስተማቕሮ',
    tipDesc1: 'ኣብ ኩሉ ሰቀላታትን ህያው ዥረታትን ዝተኣሳሰረ ኣገልግሎትና 10% ጥራይ እዩ ዝመጽእ ፣ እዚ ድማ ምስቲ ንቡር 60% ናይ ቲክቶክን ካልኦት መራሕቲ ኢንዱስትሪን ክኽፈል ከሎ ፣ ከምኡ\'ውን ኣብ ናይ ቪድዮ ስረዛታት ድምጺ ክህብ ይኽእል እዩ ፣ እዚ ድማ ነቲ ሓይሊ ናብ ኢድ ተመልካቲ ዘመልክት እዩ ።',
    tipDesc2: 'ንተዓዘብቲ ዝቕበሉ ምኽርታትን ምኽርታትን ኣብ ዝተፈላለዩ መራሕቲ ቦርዶታት ከምኡ\'ውን ኣብ ኣታዊታት ኣክሲዮናት ዝውስኑ ተዓዘብቲ ቆጸራትን ተመዝጋቢታትን ተመዝጊቦም ኣለዉ ። እቶም ተሳተፍቲ ናይ DeHub ምልክታት ነቲ ናይ ሓፈሻዊ ፕሮቶኮል ረብሓ ሚዛናዊ ኣክሲዮኖም ይረኽቡ እዮም ።',
    mineSubtitle: 'ዲክታላይዜሽን ሚዛናዊ ምህርቲን ናይ ኣታዊ ኣክሲዮን ሞዴል',
    mineDesc1: 'ገለ ጥራይ እዮም ልዕሊ 50 ሚልዮን DeHub ምልክታት ዝሕዝዎ ፣ መብዛሕትኦም ድማ ናይ ስራሕ ቦርሳታት እዮም ፣ እቶም ዝተረፉ ድማ ኣባላት ማሕበረሰብ እዮም ።',
    mineDesc2: 'እቲ ቀንዲ ጋንታ ወይ ናይ ላዕለዋይ ደረጃ ባጅ ዘለዎም ጥራይ እዮም ነቲ ዝተኣሳሰረ NFT ብምቃጸል ቪድዮ ብኡብኡ ክስወሩ ዝኽእሉ ። ድሕሪኡ ፡ እቲ ዝተፈጥረ ኩሉ ኣታዊታት ኣፕልትን ዝኾነ ይኹን ምስ ኩሎም ናይ ድምጺ ቦርሳታት ብምትሕብባር ፡ ነቲ ሕማቕ ተዋሳእቲ ንምግታእን ንተሳትፎ ማሕበረሰብ ንምትብባዕን ክካፈል እዩ ።',
    mineDynamic: 'እቲ ንኹሉ ጥቕሚ ዘድሊ ናይ DeHub ምልክታት መጠን ተለዋዋጭ ስለዝኾነ ኣብ ዝኾነ እዋን ምስ ዋጋ ክለዋወጥ ኣለዎ ። ዝኾነ ለውጢ ኣብ ኩሉ ወግዓዊ ቻነላት ብወግዒ ክግለጽ እዩ ።',
    govTitle: 'ምምሕዳር + ሚዛናዊ ስርዓት ዲዛይን',
