    feedsDesc: 'እቲ DeHub ናይ ገዛ ገጽ ንነፍሲ ወከፍ ቅርጸት ትሕዝቶ ብሓንሳብ ዝሸከም ሓደ ዝተረጋገጸ መግብን እዩ ። ኣብ ክንዲ ንፈጣሪያት ኣብ ሓደ ሜድያ ዝገድድ ፡ እቲ ምግቢ ጽሑፍ ፡ ስእሊ ፡ ነዊሕ ቅርጺ ዘለዎ ቪድዮ ፡ ሓጺር ቅርጺ ዘለዎ ሪል ፡ ሙዚቃን ህያው ዥረታትን ኣብ ሓደ መጽሓፍ ይትኣሳሰር ፡ ተመልካቾች ድማ ኣብ ዝደለዩሉ እዋን ናብ ሓደ ቅርጸት ይሓጽሩ ። ነፍሲ ወከፍ ካርታ ፡ ብዘየገድስ ቅርጸት ፡ ሓደ ዓይነት ማሕበራዊን ሞኒተላይዜሽን መቆጣጠሪታት ይሕዝ ፡ ንኣብነት ፡ ርእይቶ ፡ ዳግመ-ግምገማ ፡ ጥቕሲ ፡ መእተዊ ፡ መእተዊ ፡ ከምኡውን መእተዊ ኣብ DeHub ምልክታት ።',
    feedsDesc2: 'ቅርጺታት ከም ታብታት ኣብ ላዕሊ እቲ መግብን ይቐርቡ እዮም ። እቲ ነባሪ ናይ ገዛ ታብ ካብ እትስዕቦ ሰባትን ማሕበረሰባትን ኩሉ ነገር ይኣሳሰር ፣ እቲ ዝተወፈየ ታብታት ሓደ ሜድያ የፈልየካ ፣ ንኣብነት ፡ ነዊሕ ቪድዮ ወይ ሙዚቃ ጥራይ ክትመርምር ትኽእል ኢኻ ። እቲ ደረጃ ካብ\'ዚ ገጽ\'ዚ ብዝያዳ ዝተመዝገበ ናይ መድረኽ መራሒ ስልተ ቀመር እዩ ዝንቀሳቐስ ፣ ስለዚ ጥዕናን ተሳትፎን ፣ ናይ ኣፕል ወፃኢ ዘይኮነ ፣ ናይ ምብጻሕ ውሳነ ይገብር ።',
    feedsHome: 'መግብን መግብን ፦',
    feedsShorts: 'ኣጻብዕታት ፦',
