    feedsPolls: 'ምርጫታት ፦',
    feedsPollsDesc: 'ናይ ድምጺ ቦታታት ፍጠርን ኣብ መግቢ ድምጺ ምእካብን ። ውጽኢት ብቀጥታ ዝቕጽል ኮይኑ ፡ ንማሕበረሰብ ውሳነታት ወይ ስምዒታት ምምሕዳር ንምምራሕ ክውዕል ይኽእል እዩ ።',
