    feedsBookmarks: 'መእተዊታትን መመርመሪ ሰሌዳታትን ፦',
    feedsBookmarksDesc: 'ንዝያዳ ጽሑፍ ናብ ናይ ውልቀ-መጽሓፍቲካ ጸኒሕካ ኣድሕን ፣ ነቲ ኣብ ታሕቲ ዘሎ ስልተ ቀመር ዝተገልጸሉ ኣብ መድረኽ መሪሕነት ዘሎ ላዕለዎት ፈጣራት ድማ ክትከታተሎ ኢኻ ።',
