    walletHubB2: 'ማእከል ኣመራርሓ ፦',
    walletHubB2Desc: 'ናይ ፈጣር ፋይናንስ ዳሽቦርድ ምስ ግዜ ናይ ኣታዊ ካርታታት ፣ ናይ ምትሕልላፍ ምብትታን ናይ መስቀል ሰንሰለት ናይ ኣታዊ ዳሽቦርድ ።',
