    kidsTitle: 'ኣብድርግ ኣብድርግ',
    kidsDesc: 'ናይ ቈልዑ ሞድ መሳርሒ ናብ ናይ ቈልዑ ቦታ ይቕይር ። በዚ ድማ DeHub ንፈጣሪያቶም ኣብ ኩሉ ቦታ ኣብ ኣፕሊኬሽን ንዝተሓትሙ ህጻናት ጥራይ እዩ ዝሕብር ፣ ርኹስ ወይ ብጁ ኢሞጂታት ድማ ይዕቀቡ ። ኣብ DeHub ካልእ ነገር ናብ ሓደ ቆልዓ ኣይበጽሕን እዩ ።',
    kidsB1: 'ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣብስተዋል ኣብ ምስራሕ ኣ',
    kidsB2Desc: 'ፈጣራት "Made for Children" ዝብል ጽሑፍ ኣብ ደራሲኦም ብምስኣል ነዚ ኣረጋጊጾምዎ እዮም ። እቲ ጽሑፍ ኣብ Kids Mode እዩ ዝግለጽ ፣ ካብ ተራ ምግቢ ይወጽእ ፣ ኣብ መገለጺ ፈጣሪ ይጸንሕ ፣ ኣብ ምድላይ ድማ ይጸንሕ ፣ ብዛዕባኡ ድማ ናይ ቈልዑ Mode ጥራይ እዩ ክገልጽ ዝኽእል ። ሓደ ቦታ ንቘልዑ ብስለት ኪህልዎ ኣይክእልን እዩ ።',
