    govLiveDesc: 'እቲ ኣብ ላዕሊ ዘሎ ንድፊ ፡ ምምሕዳር እንታይ እዩ ፧ እቲ ናይ ምምሕዳር ገጽ ፡ እቲ ዚፍጸምሉ ቦታ እዩ ። እቲ ፕሮፖዛላት ኣብ ትሕቲ ፕሮፖዛላት ፣ ፓስደን ዝተነጸረ ፣ ነፍሲ ወከፍ ምስ ደራሲኡ ፣ ጽሑፍኡን እቲ ድምጺ ዘለዎ ቦታን ተዘርዚሩ ኣሎ ። ሓደ ሓሳብ ምኽፋት ናይ 10,000 DeHub ምልክታት ክፍሊት የኽፍል ፣ ኣብ ሰንሰለት ተረጋጊጹ ፣ ነፍሲ ወከፍ ሓሳብ ድማ ናይ ባዕሉ ገጽ ኣለዎ ። እቲ ድምጺ ብናጻ እዩ ፦ እቲ ድምጺኻ ብባጅኻ ክብደት ኣለዎ ፡ ንሸውዓተ መዓልታት ይካየድ ፡ እቲ ሓሳብ ድማ ብውሑዱ ዓሰርተ ዝተፈላለዩ ናይ ቦርሳታት ድምጺ ሒዙ ፡ ሓደ ሰብ ዘይረኣዮ ነገር ክሓልፍ ኣይክእልን እዩ ።',
