    howItWorksDesc2: 'እዚ ድማ ንብዘላ ስነ ምህዳር ጥራይ ዘይኰነስ ንብዘላ ኣካል እውን ይጠቅም እዩ ። ፈጣራት ትሕዝቶ ፡ ሸማቾች ፡ ሓላቑን ኩባንያታትን ኣብ መድረኽ ዝእውጁ ፡ ዝያዳ ዓስቢ ይረኽቡ እዮም ።',
    howItWorksDesc3: 'እቲ ናይ ገንዘብ ሓበሬታ እቲ ኣዝዩ ረብሓ ዘለዎ እዩ ፣ ናትና ድማ ኣብ ሓደ ናይ ስርዓት ኣወሃሃሃዲታት ንተዓዘብቲ ንምምልካት ክጥቀሙሉ ዝኽእሉ ሓደ እዩ ። እዚ ዋላ\'ውን ክትገብሮ እትኽእል ነገር ኣይኮነን ፣ ምኽንያቱ ናይ ባንክ መግለጺታት ብሕታዊ ስለዝኾኑ ፣ እቲ ባንክ ግን ህዝባዊ እዩ ።',
    howItWorksDesc4: 'ኣብ ባሕሪ ንዝርከቡ ንኣሽቱ ዓሳታት ፍሉይ ቅናሾት ወይ ቅናሾት ብምምዝጋብ ፡ ዓሳታትን ዓበይቲ ወፃኢታትን ንምምልካት ፡ ኣብ መላእ ዓለም ብኸመይ ከም ዚሰርሕ ፡ ኣብ መላእ ዓለም ፡ ኣፕልቲስቲክስ ብኸመይ ከም ዚሰርሕ ኪገልጽ እዩ ። ስለምንታይ እዩ እዚ ዘይደሊ ፧',
