    requestFullBrandKitDesc: 'ን SVG ፣ EPSን ካልኦት ቅርጸታት ቬክተርን ወይ ኣብዚ ዘይተገልጸ ንብረት እንተድኣ ዘድልየካ ፡ ምስ ናይ ብራንድ ጉጅለና ርክብ ግበር ።',
