    businesses: 'ንግዲ',
    businessesText: 'ነቲ ኣገልግሎት ብስም ሓደ ትካል ወይ ትካል ትጥቀመሉ እንተ ዄንካ ፡ ነቲ ትካል ኣብ ክንዲ እቲ ትካል ክትሰርሕ ስልጣን ከም ዘሎካ ፡ እቲ ትካል ድማ ነዚ ስምምዕነት እዚ ከም ዝቕበልካ ትኣምን ኢኻ ።',
