    feesAndGas: 'ናይ ጋዝ ወጻኢታትን ወጻኢታትን',
    feesAndGasText: 'ነፍሲ ወከፍ ናይ ምልክት መግዛእቲ ናይ ጋዝ ወጻኢታትን ናይ ኣገልግሎት ወጻኢታትን ንምሽፋን ተወሳኺ 1% ክፍሊት የጠቓልል ። እዚ ክፍሊት እዚ ኣብ ናይ መርበብ ኩነታትን ኣብ ናይ ሳልሳይ ወገን ኣገልግሎት ወሃቢታትን ተመርኲሱ ክፈላለ ይኽእል እዩ ።',
