    fiatOnRampItem3: 'ናይ ሳልሳይ ወገን ናይ ኣገልግሎት ክፍሊት ወይ ክፍሊት',
    fiatOnRampItem4: 'ምስ ናይ ከባቢኻ ናይ ክፍሊት ሕግታት ኣብ ስልጣንካ ተሰማሚዕካ',
