    q25: 'ብሓቂ እንታይ እዩ ዚገብረኒ ፧',
    a25: 'ሓደ ባጅ ነቲ ናይ መድረኽ ክፍሊትካ ብ 0.69% ኣብ ሓደ ደረጃ ይንእስ ፣ ነቲ ናይ መዓልታዊ ልኡኽኻትካ ብነጻ የዕብዮ ፣ ነቲ ዝሓለፈ ዝኾነ ነገር ድማ ይንእስ ፣ ነቲ ናይ DeHub ምልክታት ምስ እትዕድግ ድማ ተመሳሳሊ 5% -30% ቅናሽ ይህበካ ፣ ንልዕለ-ኃይልን መገለጺን ኮስመቲካን ይኽፍት ፣ ርእይቶኻን ግብረመልስን ድማ ዝያዳ ይቑጸር ። እቶም 13 ደረጃታት ኣብ ክንዲ ሓደ ውሱን ቁጽሪ ምልክታት ብዶላር እዮም ዝሽየጡ ፣ ሓደ ግዜ ድማ ሓደ ነጥቢ ምስ ረኸብካ እቲ ዋጋ ክመልሰካ ኣይክእልን እዩ ።',
